=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md and microarchitecture.md for rr_arbiter.
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    // Pointer width and exact-width constants.
    localparam integer  PW       = (N > 1) ? $clog2(N) : 1;
    localparam integer  LAST_I   = N - 1;
    localparam integer  ONE_I    = 1;
    localparam [PW-1:0] LAST     = LAST_I[PW-1:0];
    localparam [PW-1:0] PTR_ONE  = ONE_I[PW-1:0];
    localparam [PW-1:0] PTR_ZERO = {PW{1'b0}};

    // State: the priority pointer (highest-priority requester this cycle).
    reg  [PW-1:0] ptr;

    // Combinational results.
    reg  [PW-1:0] ptr_next;
    reg  [PW-1:0] winner;
    reg           found;
    reg  [PW-1:0] idx;
    integer       k;

    // Grant logic: wrapping priority search from ptr, wrap at N-1 -> 0.
    always @* begin
        grant  = {N{1'b0}};
        winner = PTR_ZERO;
        found  = 1'b0;
        idx    = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                found      = 1'b1;
                winner     = idx;
                grant[idx] = 1'b1;
            end
            if (idx == LAST) idx = PTR_ZERO;
            else             idx = idx + PTR_ONE;
        end
    end

    // Pointer update: one past the winner on a grant, hold otherwise.
    always @* begin
        ptr_next = ptr;
        if (found) begin
            if (winner == LAST) ptr_next = PTR_ZERO;
            else                ptr_next = winner + PTR_ONE;
        end
    end

    // Pointer register: synchronous, active-low reset to 0.
    always @(posedge clk) begin
        if (!rst_n) ptr <= PTR_ZERO;
        else        ptr <= ptr_next;
    end

`ifdef FORMAL
    // Design-intent properties (unproven until a job file runs them).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // Distance from 'from_i' upwards to 'to_i', wrapping at N.
    function [PW:0] f_dist;
        input [PW-1:0] from_i;
        input [PW-1:0] to_i;
        begin
            if (to_i >= from_i) f_dist = {1'b0, to_i} - {1'b0, from_i};
            else                f_dist = {1'b0, to_i} + N - {1'b0, from_i};
        end
    endfunction

    always @(*) begin
        if (f_past_valid) begin
            assert(ptr <= LAST);
            assert((grant & (grant - 1'b1)) == {N{1'b0}});
            assert((grant & ~req) == {N{1'b0}});
            assert(found == (req != {N{1'b0}}));
            if (req != {N{1'b0}}) assert(grant != {N{1'b0}});
            if (found) assert(grant[winner]);
            cover(rst_n && (req == {N{1'b1}}));
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))     assert(ptr == PTR_ZERO);
            else if ($past(found)) assert(ptr == (($past(winner) == LAST) ? PTR_ZERO : ($past(winner) + PTR_ONE)));
            else                   assert(ptr == $past(ptr));
            if ($past(rst_n) && $past(found)) cover(($past(winner) == LAST) && (ptr == PTR_ZERO));
        end
    end

    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : f_req
            reg [PW:0] f_wait;
            initial f_wait = {(PW+1){1'b0}};
            always @(posedge clk) begin
                if (!rst_n || !req[g] || grant[g]) f_wait <= {(PW+1){1'b0}};
                else                               f_wait <= f_wait + 1'b1;
            end
            always @(*) begin
                if (f_past_valid) begin
                    if (found && req[g]) assert(f_dist(ptr, g) >= f_dist(ptr, winner));
                    assert(f_wait <= LAST);
                    if (f_wait != {(PW+1){1'b0}}) assert((f_wait + f_dist(ptr, g)) <= LAST);
                    cover(grant[g]);
                end
            end
        end
    endgenerate
`endif

endmodule

`default_nettype wire
=== END FILE ===
