// rr_arbiter_tb: self-checking testbench for rr_arbiter at N=4 and N=5.
`default_nettype none

module rr_arbiter_tb;

    reg         clk;
    reg         rst_n;
    reg  [4:0]  req;
    wire [3:0]  grant4;
    wire [4:0]  grant5;

    rr_arbiter #(.N(4)) dut4 (.clk(clk), .rst_n(rst_n), .req(req[3:0]), .grant(grant4));
    rr_arbiter #(.N(5)) dut5 (.clk(clk), .rst_n(rst_n), .req(req),      .grant(grant5));

    integer         passed;
    integer         failed;
    integer         cycle;
    integer         ptr_m  [0:1];
    integer         wait_m [0:9];
    reg  [9:0]      cov_m;
    reg  [9:0]      alone_m;
    reg  [4:0]      prev_req;
    reg  [31:0]     rng;
    reg  [8*64-1:0] nonce;
    integer         win;
    integer         j;
    integer         k;
    integer         i;
    integer         t;
    reg             fair_ok;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Deterministic xorshift32, identical in every simulator.
    task rand_bits;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // Check one arbiter lane against the reference pointer model for this
    // cycle, track fairness and coverage, then advance the model as the
    // coming rising edge will.
    // cov_m bits per lane: 0 none, 1 all, 2 wait N-1, 3 reset in traffic,
    // 4 held request among changing others.
    task check_lane;
        input integer lane;
        input integer n;
        input [4:0]   g;
        reg   [4:0]   lm;
        reg   [4:0]   exp_g;
        reg   [4:0]   others;
        integer       base;
        begin
            base = lane * 5;
            lm   = (5'b00001 << n) - 5'b00001;

            win = -1;
            for (k = 0; k < n; k = k + 1) begin
                j = (ptr_m[lane] + k) % n;
                if (win < 0 && req[j]) win = j;
            end
            exp_g = 5'b00000;
            if (win >= 0) exp_g = 5'b00001 << win;

            if (g === exp_g) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: req %b ptr %0d rst_n %b: grant %b, expected %b",
                       n, cycle, req & lm, ptr_m[lane], rst_n, g, exp_g);
            end

            if (rst_n) begin
                if ((req & lm) == 5'b00000) cov_m[base + 0] = 1'b1;
                if ((req & lm) == lm)       cov_m[base + 1] = 1'b1;
                for (i = 0; i < n; i = i + 1)
                    if (((req & lm) == (5'b00001 << i)) && g[i]) alone_m[base + i] = 1'b1;
            end else if ((req & lm) != 5'b00000) begin
                cov_m[base + 3] = 1'b1;
            end

            fair_ok = 1'b1;
            for (i = 0; i < n; i = i + 1) begin
                others = (req ^ prev_req) & lm & ~(5'b00001 << i);
                if (rst_n && req[i] && (wait_m[base + i] > 0) && (others != 5'b00000))
                    cov_m[base + 4] = 1'b1;
                if (rst_n && req[i] && !g[i]) wait_m[base + i] = wait_m[base + i] + 1;
                else                          wait_m[base + i] = 0;
                if (wait_m[base + i] == n - 1) cov_m[base + 2] = 1'b1;
                if (wait_m[base + i] > n - 1) begin
                    fair_ok = 1'b0;
                    $error("N=%0d cycle %0d: requester %0d has waited %0d cycles (bound %0d)",
                           n, cycle, i, wait_m[base + i], n - 1);
                end
            end
            if (fair_ok) passed = passed + 1;
            else         failed = failed + 1;

            if (!rst_n)        ptr_m[lane] = 0;
            else if (win >= 0) ptr_m[lane] = (win + 1) % n;
        end
    endtask

    // One cycle: drive at the falling edge, check the settled grant.
    task step;
        input [4:0] r;
        input       rn;
        begin
            @(negedge clk);
            req   = r;
            rst_n = rn;
            #1;
            cycle = cycle + 1;
            check_lane(0, 4, {1'b0, grant4});
            check_lane(1, 5, grant5);
            prev_req = r;
        end
    endtask

    // Independent strict-rotation check: s cycles after reset, all requesting.
    task check_rot;
        input integer s;
        begin
            if ((grant4 === (4'b0001 << (s % 4))) && (grant5 === (5'b00001 << (s % 5)))) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("rotation step %0d: grant4 %b grant5 %b", s, grant4, grant5);
            end
        end
    endtask

    task check_cov;
        input integer lane;
        input integer n;
        reg   [4:0]   lm;
        begin
            lm = (5'b00001 << n) - 5'b00001;
            if ((cov_m[lane*5 +: 5] == 5'b11111) && ((alone_m[lane*5 +: 5] & lm) == lm)) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("coverage gap at N=%0d: cases %b, alone %b",
                       n, cov_m[lane*5 +: 5], alone_m[lane*5 +: 5]);
            end
        end
    endtask

    initial begin
        passed   = 0;
        failed   = 0;
        cycle    = 0;
        req      = 5'b00000;
        rst_n    = 1'b0;
        prev_req = 5'b00000;
        cov_m    = 10'b0000000000;
        alone_m  = 10'b0000000000;
        rng      = 32'h1234_5678;
        fair_ok  = 1'b1;
        nonce    = {(8*64){1'b0}};
        ptr_m[0] = 0;
        ptr_m[1] = 0;
        for (t = 0; t < 10; t = t + 1) wait_m[t] = 0;

        // Power-up reset: two reset edges before any check.
        @(negedge clk);
        @(negedge clk);

        // 1. Reset held, with and without traffic: grant follows req.
        step(5'b00000, 1'b0);
        step(5'b11111, 1'b0);
        step(5'b01010, 1'b0);

        // 2. No requests.
        for (t = 0; t < 3; t = t + 1) step(5'b00000, 1'b1);

        // 3. Each requester alone.
        for (t = 0; t < 5; t = t + 1) begin
            step(5'b00001 << t, 1'b1);
            step(5'b00001 << t, 1'b1);
        end

        // 4. Everyone requesting from reset: strict rotation 0, 1, ..., N-1.
        step(5'b00000, 1'b0);
        for (t = 0; t < 20; t = t + 1) begin
            step(5'b11111, 1'b1);
            check_rot(t);
        end

        // 5. Reset during full traffic: rotation restarts at 0.
        step(5'b11111, 1'b0);
        for (t = 0; t < 10; t = t + 1) begin
            step(5'b11111, 1'b1);
            check_rot(t);
        end

        // 6. A held request among changing others.
        for (t = 0; t < 60; t = t + 1) begin
            rand_bits;
            step(rng[4:0] | 5'b00100, 1'b1);
        end
        for (t = 0; t < 60; t = t + 1) begin
            rand_bits;
            step(rng[4:0] | 5'b01000, 1'b1);
        end

        // 7. Random traffic: drops, raises, occasional reset.
        for (t = 0; t < 800; t = t + 1) begin
            rand_bits;
            step(rng[4:0], (rng[12:8] != 5'b00000));
        end

        // 8. Sparse random traffic.
        for (t = 0; t < 200; t = t + 1) begin
            rand_bits;
            step(rng[4:0] & rng[9:5] & rng[14:10], 1'b1);
        end

        step(5'b00000, 1'b1);

        check_cov(0, 4);
        check_cov(1, 5);

        if (passed == 0) begin
            failed = failed + 1;
            $error("no check passed");
        end

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
